import React, { PropsWithChildren } from "react";
import clsx from "clsx";
import { Breadcrumb as BreadcrumbStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import { CommonProps } from "../helperTypes";

const useStyles = createUseStyles(BreadcrumbStyles, "breadcrumb");

type Props = PropsWithChildren<{
  /** Specify the label for the breadcrumb `nav` container */
  "aria-label"?: string;
  /**
   * Specify the size of the breadcrumb
   * @default small
   */
  size?: "small" | "medium";
}>;

export type BreadcrumbProps = Props & CommonProps;

const Breadcrumb = (props: BreadcrumbProps) => {
  const {
    "aria-label": ariaLabel = "breadcrumb",
    className,
    children,
    size = "small",
    ...rest
  } = props;
  const classes = useStyles();

  return (
    <nav aria-label={ariaLabel}>
      <ol
        className={clsx(
          classes.root,
          className,
          size === "medium" && classes._medium
        )}
        {...rest}
      >
        {React.Children.map(children, (child) => {
          if (!React.isValidElement(child)) return null;
          if (child.type === React.Fragment) {
            console.warn(
              "[AIRBUS-DS] The Breadcrumb component doesn't accept a Fragment as a child. Consider providing an array instead."
            );
          } else if (child.type !== BreadcrumbItem) {
            console.warn(
              "[AIRBUS-DS] The Breadcrumb component only accept BreadcrumbItem as children."
            );
          }
          return child;
        })}
      </ol>
    </nav>
  );
};

export default Breadcrumb;

export type BreadcrumbItemProps = PropsWithChildren<{
  /** Provide if this item represents the current page */
  current?: boolean;
}> &
  CommonProps;

export const BreadcrumbItem = (props: BreadcrumbItemProps) => {
  const { children, className, current, ...rest } = props;
  const classes = useStyles();

  return (
    <li
      className={clsx(className, classes.item, {
        [classes.item_current]: current,
      })}
      {...rest}
    >
      {children}
    </li>
  );
};
